import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s5-u06")
C = "B1"

L(1, "Água: viver abaixo do nível do mar", "de dijk, de polder, het waterschap, NAP",
  ["Conhecer o vocabulário da gestão da água nos Países Baixos"],
  vocab=[V("v-dijk","dijk","dique","noun","de"), V("v-polder","polder","pólder","noun","de"),
         V("v-waterschap","waterschap","autoridade regional da água","noun","het"), V("v-zeespiegel","zeespiegel","nível do mar","noun","de"),
         V("v-overstroming","overstroming","inundação","noun","de")],
  ex=[("Een groot deel van Nederland ligt onder de zeespiegel.","Grande parte dos Países Baixos fica abaixo do nível do mar."),("De dijken beschermen ons tegen het water.","Os diques protegem-nos da água."),("In 1953 was er een grote overstroming.","Em 1953 houve uma grande inundação."),("Het waterschap zorgt voor de dijken.","A autoridade da água trata dos diques.")],
  gram=[G("g-water-nl","Água e passiva com worden","Cerca de um quarto do país está abaixo do nível do mar. Os **polders** são terrenos ganhos ao mar, protegidos por **dijken** e drenados por bombas (antigamente moinhos). Em textos sobre o tema aparece muito a passiva: *Het water **wordt** weggepompt.*",
    [("Na 1953 zijn de Deltawerken gebouwd.","Depois de 1953 foram construídas as obras do Delta.")])],
  review=["v-water","v-zee","v-land"],
  cefr=C, exs=[
    MA([("dijk","dique"),("polder","pólder"),("waterschap","autoridade da água"),("zeespiegel","nível do mar"),("overstroming","inundação")], "Água.", ["v-dijk","v-polder","v-waterschap","v-zeespiegel","v-overstroming"]),
    TR("pt-nl","Os diques protegem-nos da água.", ["De dijken beschermen ons tegen het water"], "beschermen tegen.", ["v-dijk"]),
    TR("nl-pt","Een groot deel van Nederland ligt onder de zeespiegel.", ["Grande parte dos Países Baixos fica abaixo do nível do mar","Uma grande parte dos Países Baixos está abaixo do nível do mar"], "liggen onder.", ["v-zeespiegel"]),
    AR("waterschap","a autoridade da água","het", "Het waterschap.", ["v-waterschap"]),
    AR("overstroming","a inundação","de", "-ing → de.", ["v-overstroming"]),
    MC("Um pólder é…", ["*terreno ganho ao mar ou a um lago, protegido por diques","uma montanha|Os Países Baixos quase não têm.","um rio|Não."], "Polder.", ["v-polder"]),
    MC("O que aconteceu em 1953?", ["*A Watersnoodramp, uma grande inundação na Zelândia","A independência|Não.","O primeiro Koningsdag|Não."], "Watersnood.", ["v-overstroming"]),
    LI("Het water wordt uit de polder gepompt.", ["Het water wordt uit de polder gepompt"], "A água é bombeada para fora do pólder.", "Passiva.", ["v-polder"]),
    FE(["De","dijken","beschermt","het","land."], 2, "beschermen", "Sujeito plural (de dijken): beschermen.", ["v-dijk"]),
    CO("text","De Deltawerken", "Na de overstroming van 1953, waarbij meer dan 1800 mensen omkwamen, besloot de regering het zuidwesten van Nederland beter te beschermen. Zo ontstonden de Deltawerken: een systeem van dammen, sluizen en stormvloedkeringen. De Oosterscheldekering kan bij storm worden gesloten, maar staat normaal open, zodat de natuur gezond blijft.",
       [("Porque foram construídas as Deltawerken?", ["*Para proteger o sudoeste depois da inundação de 1953","Para produzir energia","Para o turismo"]),("Porque fica a barreira do Oosterschelde normalmente aberta?", ["*Para manter a natureza saudável","Porque está avariada","Para os barcos de pesca pagarem"])],
       "omkomen = morrer (num acidente/catástrofe).", ["v-overstroming","v-dijk"]),
  ], diff=4, mins=7)

L(2, "Energia e casa", "zonnepanelen, de energierekening, isoleren, warmtepomp",
  ["Falar de energia doméstica e poupança"],
  vocab=[V("v-zonnepanelen","zonnepanelen","painéis solares","noun","de"), V("v-energierekening","energierekening","fatura da energia","noun","de"),
         V("v-isoleren","isoleren","isolar","verb"), V("v-besparen","besparen","poupar (energia)","verb"),
         V("v-warmtepomp","warmtepomp","bomba de calor","noun","de")],
  ex=[("We hebben zonnepanelen op het dak.","Temos painéis solares no telhado."),("De energierekening is flink gestegen.","A fatura da energia subiu bastante."),("Door het huis te isoleren bespaar je energie.","Isolando a casa poupas energia."),("Steeds meer huizen hebben een warmtepomp.","Cada vez mais casas têm bomba de calor.")],
  gram=[G("g-door-te","Door … te + infinitivo","**door** + **te** + infinitivo = «ao…/fazendo…» (meio): *Door het huis **te isoleren** bespaar je energie.* A seguir à oração com door vem a inversão (verbo-sujeito).",
    [("Door minder te douchen bespaar je water.","Tomando duches mais curtos poupas água.")],
    "Corresponde ao nosso gerúndio de meio («isolando a casa…»).")],
  review=["v-verwarming","v-licht","v-duur"],
  cefr=C, exs=[
    MA([("zonnepanelen","painéis solares"),("energierekening","fatura da energia"),("isoleren","isolar"),("besparen","poupar"),("warmtepomp","bomba de calor")], "Energia.", ["v-zonnepanelen","v-energierekening","v-isoleren","v-besparen","v-warmtepomp"]),
    WO("Isolando a casa poupas energia.", ["Door","het","huis","te","isoleren","bespaar","je","energie"], "door … te + inversão.", ["v-isoleren","v-besparen"]),
    TR("pt-nl","Temos painéis solares no telhado.", ["We hebben zonnepanelen op het dak","Wij hebben zonnepanelen op het dak"], "op het dak.", ["v-zonnepanelen"]),
    TR("nl-pt","De energierekening is flink gestegen.", ["A fatura da energia subiu bastante","A conta da energia subiu muito"], "flink = bastante.", ["v-energierekening"]),
    FE(["Door","minder","douchen","bespaar","je","water."], 2, "te douchen", "door + te + infinitivo: door minder te douchen.", ["v-besparen"]),
    MC("O que é «sparen» vs «besparen»?", ["*sparen = juntar dinheiro; besparen = gastar menos (energia, custos)","São sinónimos perfeitos|Há diferença de uso.","besparen = gastar mais|Ao contrário."], "Nuance.", ["v-besparen"]),
    AR("warmtepomp","a bomba de calor","de", "De pomp.", ["v-warmtepomp"]),
    LI("Hoeveel bespaar je met zonnepanelen?", ["Hoeveel bespaar je met zonnepanelen"], "Quanto se poupa com painéis solares?", "besparen.", ["v-besparen"]),
    FB("Een goed ___ huis heeft minder verwarming nodig.", ["geïsoleerd"], "Particípio adjetival.", ["v-isoleren"], choices=["geïsoleerd","isoleren","isoleert"], tr="Uma casa bem isolada precisa de menos aquecimento."),
    SW("Dê 2 dicas para poupar energia em casa, usando «door … te».", ["Door de verwarming een graad lager te zetten bespaar je veel. Door korter te douchen bespaar je ook energie."], ["**door … te** + infinitivo", "Inversão depois (**bespaar je**)", "Duas dicas"], 15, "Dicas de poupança.", ["v-besparen"]),
  ], diff=4, mins=7)

L(3, "Reciclar e separar o lixo", "afval scheiden, plastic, gft, glasbak, statiegeld",
  ["Saber separar o lixo e falar de reciclagem"],
  vocab=[V("v-afval","afval","lixo|resíduos","noun","het"), V("v-scheiden","scheiden","separar","verb",note="afval scheiden"),
         V("v-gft","gft","resíduos orgânicos (fruta, legumes, jardim)","noun","het"), V("v-statiegeld","statiegeld","depósito (garrafas/latas)","noun","het"),
         V("v-kliko","container","contentor do lixo","noun","de",note="regionalmente «kliko»")],
  ex=[("Wij scheiden ons afval.","Nós separamos o nosso lixo."),("Groenteresten gaan in de gft-bak.","Restos de legumes vão para o contentor orgânico."),("Op deze fles zit statiegeld.","Esta garrafa tem depósito."),("Glas gooi je in de glasbak.","O vidro deita-se no vidrão.")],
  review=["v-fles","v-papier","v-vuil"],
  cefr=C, exs=[
    MA([("afval","lixo"),("scheiden","separar"),("gft","orgânico"),("statiegeld","depósito"),("container","contentor")], "Reciclagem.", ["v-afval","v-scheiden","v-gft","v-statiegeld","v-kliko"]),
    MC("Uma casca de banana vai para…", ["*de gft-bak","de glasbak|Vidro.","het plastic|Plástico."], "Orgânico.", ["v-gft"]),
    MC("Garrafas de plástico pequenas e latas com statiegeld…", ["*devolvem-se no supermercado e recebe dinheiro de volta","deitam-se no lixo normal|Perde o depósito.","guardam-se para sempre|Não."], "Statiegeld.", ["v-statiegeld"]),
    TR("pt-nl","Nós separamos o nosso lixo.", ["Wij scheiden ons afval","We scheiden ons afval"], "afval scheiden.", ["v-afval","v-scheiden"]),
    TR("nl-pt","Op deze fles zit statiegeld.", ["Esta garrafa tem depósito","Esta garrafa tem tara","Há depósito nesta garrafa"], "statiegeld.", ["v-statiegeld"]),
    AR("afval","o lixo","het", "Het afval.", ["v-afval"]),
    FE(["Ons","afval","worden","op","dinsdag","opgehaald."], 2, "wordt", "Het afval é singular: wordt.", ["v-afval"]),
    LI("Het oud papier wordt elke twee weken opgehaald.", ["Het oud papier wordt elke twee weken opgehaald","Het oude papier wordt elke twee weken opgehaald"], "O papel velho é recolhido de duas em duas semanas.", "Passiva.", ["v-afval"]),
    FB("Lege flessen gooi je in de ___.", ["glasbak"], "Vidrão.", [], choices=["glasbak","gft-bak","brievenbus"], tr="As garrafas vazias deitam-se no vidrão."),
    CO("text","Afvalkalender", "In onze gemeente wordt het restafval elke twee weken op maandag opgehaald. De gft-container gaat in de zomer elke week, in de winter om de twee weken. Plastic, blik en drinkpakken mogen samen in de oranje container. Grofvuil, zoals een oude bank, moet je zelf naar het afvalbrengstation brengen of op afspraak laten ophalen.",
       [("Para onde vão as latas?", ["*Para o contentor laranja, com o plástico","Para o orgânico","Para o vidrão"]),("O que fazer com um sofá velho?", ["*Levá-lo ao ecocentro ou marcar a recolha","Deixá-lo na rua","Pô-lo no orgânico"])],
       "grofvuil = monstros (móveis velhos).", ["v-gft","v-kliko"]),
  ], diff=4, mins=7)

L(4, "Clima e alterações climáticas", "klimaatverandering, CO₂-uitstoot, duurzaam",
  ["Discutir as alterações climáticas com vocabulário básico"],
  vocab=[V("v-klimaatverandering","klimaatverandering","alterações climáticas","noun","de"), V("v-uitstoot","uitstoot","emissões","noun","de"),
         V("v-duurzaam","duurzaam","sustentável","adjective"), V("v-opwarming","opwarming","aquecimento","noun","de"),
         V("v-milieu","milieu","ambiente","noun","het")],
  ex=[("Klimaatverandering is een groot probleem.","As alterações climáticas são um grande problema."),("We moeten de uitstoot van CO₂ verminderen.","Temos de reduzir as emissões de CO₂."),("Duurzaam leven is niet altijd makkelijk.","Viver de forma sustentável nem sempre é fácil."),("Fietsen is goed voor het milieu.","Andar de bicicleta é bom para o ambiente.")],
  review=["v-volgens","v-belangrijk","v-fietsen"],
  cefr=C, exs=[
    MA([("klimaatverandering","alterações climáticas"),("uitstoot","emissões"),("duurzaam","sustentável"),("opwarming","aquecimento"),("milieu","ambiente")], "Clima.", ["v-klimaatverandering","v-uitstoot","v-duurzaam","v-opwarming","v-milieu"]),
    TR("pt-nl","Temos de reduzir as emissões.", ["We moeten de uitstoot verminderen","Wij moeten de uitstoot verminderen","We moeten de uitstoot verlagen"], "verminderen.", ["v-uitstoot"]),
    TR("pt-nl","Andar de bicicleta é bom para o ambiente.", ["Fietsen is goed voor het milieu"], "het milieu.", ["v-milieu"]),
    TR("nl-pt","Duurzaam leven is niet altijd makkelijk.", ["Viver de forma sustentável nem sempre é fácil","Uma vida sustentável nem sempre é fácil"], "duurzaam.", ["v-duurzaam"]),
    AR("milieu","o ambiente","het", "Het milieu.", ["v-milieu"]),
    MC("«Het milieu» refere-se…", ["*ao ambiente natural","ao meio da rua|Não.","a um milhão|Não."], "milieu.", ["v-milieu"]),
    FE(["Het","is","een","duurzaam","oplossing."], 3, "duurzame", "de oplossing → een duurzame oplossing.", ["v-duurzaam"]),
    LI("Door de opwarming van de aarde stijgt de zeespiegel.", ["Door de opwarming van de aarde stijgt de zeespiegel"], "Por causa do aquecimento global o nível do mar sobe.", "opwarming.", ["v-opwarming","v-zeespiegel"]),
    WO("As alterações climáticas são um grande problema.", ["Klimaatverandering","is","een","groot","probleem"], "het probleem → groot.", ["v-klimaatverandering"]),
    SW("Escreva 2–3 frases sobre o que faz (ou podia fazer) pelo ambiente.", ["Ik fiets elke dag naar mijn werk, dus ik heb geen auto nodig. Bovendien eet ik minder vlees. Zo help ik het milieu een beetje."], ["Vocabulário da lição", "Um conector (**dus / bovendien / zo**)", "Ordem certa depois do conector"], 20, "Ações pessoais.", ["v-milieu","v-duurzaam"]),
  ], diff=4, mins=7)

L(5, "Debate: medidas ambientais", "Moet vlees duurder worden? Moeten auto's de stad uit?",
  ["Argumentar a favor e contra uma medida"],
  vocab=[V("v-maatregel","maatregel","medida","noun","de"), V("v-invoeren","invoeren","introduzir|implementar","verb"),
         V("v-belasting","belasting","imposto","noun","de"), V("v-autovrij","autovrij","sem carros","adjective")],
  ex=[("De gemeente wil een nieuwe maatregel invoeren.","A câmara quer introduzir uma nova medida."),("Er komt een belasting op vliegtickets.","Vai haver um imposto sobre os bilhetes de avião."),("Het centrum wordt autovrij.","O centro vai ficar sem carros."),("Ik ben voor deze maatregel.","Sou a favor desta medida.")],
  review=["v-aan-de-ene-kant","v-eens","v-oneens","v-omdat"],
  cefr=C, exs=[
    MA([("maatregel","medida"),("invoeren","introduzir"),("belasting","imposto"),("autovrij","sem carros")], "Políticas.", ["v-maatregel","v-invoeren","v-belasting","v-autovrij"]),
    TR("pt-nl","Sou a favor desta medida.", ["Ik ben voor deze maatregel"], "voor/tegen.", ["v-maatregel"]),
    TR("pt-nl","Sou contra este imposto.", ["Ik ben tegen deze belasting"], "tegen.", ["v-belasting"]),
    TR("nl-pt","Het centrum wordt autovrij.", ["O centro vai ficar sem carros","O centro vai ser fechado ao trânsito","O centro passa a ser sem carros"], "autovrij.", ["v-autovrij"]),
    WO("A câmara quer introduzir uma nova medida.", ["De","gemeente","wil","een","nieuwe","maatregel","invoeren"], "Infinitivo no fim.", ["v-invoeren"]),
    AR("maatregel","a medida","de", "De maatregel.", ["v-maatregel"]),
    CO("dialogue","Een autovrij centrum?", "Femke: Ik ben voor een autovrij centrum. De lucht wordt schoner en het is veiliger voor fietsers.\nKees: Aan de ene kant snap ik dat, maar aan de andere kant: hoe komen ouderen dan in de stad?\nFemke: Er kunnen elektrische busjes rijden.\nKees: Misschien. Maar de winkels verliezen klanten als mensen niet meer met de auto kunnen komen.\nFemke: Onderzoek in andere steden laat zien dat winkels juist méér klanten krijgen.",
       [("Qual é a preocupação do Kees?", ["*Os idosos e as lojas","O preço da gasolina","O barulho dos autocarros"]),("O que diz a Femke sobre as lojas?", ["*Noutras cidades até ganharam clientes","Vão fechar todas","Não lhe interessam"])],
       "snappen = perceber (coloquial).", ["v-autovrij","v-aan-de-ene-kant"]),
    FE(["Ik","ben","tegen","deze","maatregel,","omdat","het","is","te","duur."], 7, "te duur is", "omdat → verbo no fim: omdat het te duur is.", ["v-omdat"]),
    LI("De regering wil een belasting op vlees invoeren.", ["De regering wil een belasting op vlees invoeren"], "O governo quer introduzir um imposto sobre a carne.", "invoeren.", ["v-invoeren","v-belasting"]),
    SW("Seja a favor OU contra um imposto sobre os voos baratos (3 frases com um argumento e uma conclusão).", ["Ik ben voor een belasting op goedkope vluchten, omdat vliegen veel uitstoot veroorzaakt. Bovendien kan de trein dan een beter alternatief worden. Kortom: het is een goede maatregel."], ["Posição clara (**ik ben voor/tegen**)", "Argumento com **omdat** + verbo no fim", "Conclusão (**kortom**)"], 25, "Argumentação.", ["v-maatregel","v-belasting"]),
  ], diff=4, mins=8)

W()
